import re

def parse_duration(s):
    parts = re.findall(r'(\d+)([hms])', s)
    total_seconds = 0
    for part in parts:
        number = int(part[0])
        unit = part[1]
        if unit == 'h':
            total_seconds += number * 3600
        elif unit == 'm':
            total_seconds += number * 60
        elif unit == 's':
            total_seconds += number
    return total_seconds
